      "location": "서초구 서래마을 부근",
      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n택배, 운송, 배달 등 종사자 음료 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.06. 15:22\n조회 45\n구독\n택배, 운송, 배달 등 종사자 음료 좌담회\n본 조사는 좌담회 참석 전 사전과제를 수행하셔야하며, 사전과제 제출 및 좌담회 참석까지 모두하셔야 사례비가 지급됩니다.\n3~4일동안 진행되는 사전과제를 성실하게 제출하실분만 신청 부탁드립니다.\n<대상조건>\n-편의점에서 주 3회 이상 음료를 자주 구매하시는 분\n-편의점에서 비타500, 박카스, 탄산, 커피 등 다양한 음료를 주 회이상 구매하는분\n-자양강장제 작년 대비 근 6개월 구매 빈도 년 1~2회 미만으로 많이 감소한분!!\n<좌담회 일정>\n위치: 서초구 서래마을 부근\n소요시간: 2시간 30분\n시간: 8월 21일(금) 오후 7시\n<사전과제 일정>\n- 8/7(금) 사전과제 송부\n- 8/7(금)~12(수) 사전 과제 진행\n- 8/13(목)~14(금) 사전과제 수정 및 보완 기간\n<사례비>\n10만원 (사전과제+좌담회)\n*사전과제 제출 및 좌담회 참석까지 모두 완료 시 사례비 지급 가능\n<신청링크>\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey-insight.com/?ACCESS_KEY=64dc0edd-3a59-45e9-a698-d3992fe7cc75&UID=\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n* 사전과제가 동반되는 조사로 사전과제 이후 좌담회를 오시지 않을 시 대체인원 구하는게 불가능합니다. 꼭 참석 가능하신분만 신청 부탁드립니다.\n* 설문 종료 후 조건에 맞는 분께 개별적으로 연락 드릴 예정이며 신청자가 많아 마감된 대상 조건/그룹이거나 조건에 맞지 않는 부분이 있으면 연락이 가지 않을 수도 있으니 양해바랍니다.\n* 설문응답 마지막 개인정보 입력 시 소개자 이름은 필수로 입력하셔야 합니다.\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n8월중) 재혼가구 심층 인터뷰-만29~39세 재혼후 자녀를 함께 양육하시는 가정\n좌담회알바좌담회카페\n26.08.06.\n댓글\n0\n택배, 운송, 배달 등 종사자 음료 좌담회\n좌담회알바좌담회카페\n26.08.06.\n댓글\n0\n8/11) 브랜드 아파트 자2 거주 중인 50대 남녀 ) 아파트 브랜드 인식 좌담회\n좌담회알바좌담회카페\n26.08.06.\n댓글\n0\n급급급) 20분 전화 인터뷰 참여자 모집 (1~3년내 부모님 장례 치러보신 분 · 1만5천원)30~60대 여성 (성별 무관)\n좌담회알바좌담회카페\n26.08.06.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
