      "location": "에서 음료, 생수, 드링크, 커피류, 초콜릿 제품 등을 구매한 후",
      "type": "좌담회",
      "raw_content": "비대면][2026년]모바일패널 활동 참여자 모집–만20~43세 남녀 상시모집\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해\n신청 시스템이 개선\n되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n조사 개요 : 본인의 집 이외 장소에서 음료, 생수, 드링크, 커피류, 초콜릿 제품 등을 구매한 후\n제품 바코드를 촬영하고 구입 장소, 구입 가격, 음용자 정보 등을\n칸타 모바일 앱을 통해 직접 전송하는 패널 활동입니다.\n기존 가구패널, 스모커 패널과 유사하며\n좌담회·설문과 같은 일회성 참여가 아닌 지속 참여형 패널 모집입니다.\n대상 공통 조건 : 집 밖에서 음료 및 초콜릿 제품을 구매·섭취하는 분/ 스마트폰 사용자\n모집 조건 :\n조건 1\n지역 :\n서울, 경기·인천, 대전·세종, 대구, 부산·울산\n대상 : 만 20~24세 남성\n지급 기준 : 패널 가입 후 3주 이상 활동 시\n​\n조건 2\n지역 :\n서울, 경기·인천, 대전·세종, 대구, 부산·울산\n대상 : 만 20~24세 여성\n지급 기준 : 패널 가입 후 3주 이상 활동 시\n​\n조건 3\n지역 :\n경기, 대전·세종, 대구, 부산·울산\n대상 : 만 25~43세 남녀\n지급 기준 : 패널 가입 후 3주 이상 활동 시\n​\n모집 기간 : 2026년 1월 5일 ~ 모집 시까지\n방법 : 모바일 앱을 통한 비대면 패널 활동\n신청하기",
