      "raw_content": "스킨케어 화장품 좌담회-25~44세 여성 8/24~25[최대9만원]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n대상 : 25~44세 여성\n스킨케어 화장품(에센스, 크림 등)을 5일 이상 사용하는 분\n올리브영, 네이버쇼핑, 백화점 온·오프라인 등에서 스킨케어 제품을 구매하는 분\n원데이클래스, 전시회·미술관, 실내 스포츠 등의 활동을 하는 분\n대상 브랜드 : 빌리프, 라네즈, 키엘, 에스트라, 닥터지, 아누아, 세포랩, 웰라쥬, 토리든, 에스네이처,\n닥터자르트, 라로슈포제, 프리메라, 크리니크, 피지오겔, 달바\n일정 : 8/24~25\n8/24 오후 3시 : 빌리프 비이용자(25~34세)\n8/24 오후 7시 : 빌리프 이탈자(30~44세)\n8/25 오전 10시 : 빌리프 비이용자(35~44세)\n8/25 오후 3시 : 빌리프 현 이용자(30~44세)\n방법 : 좌담회\n소요시간 : 약 2시간\n사례비 : 80,000원~90,000원(그룹별 상이)\n장소 : 여의도역 인근\n조사 일정 별 및 대상 조건 모두 다릅니다. 꼭 확인바랍니다.\n▶ 화장대 사진과 파우치 사진 모두 사전 제출 필요\n▶ 현재 사용하는 화장품의 브랜드와 세부 제품명 확인 필요\n▶ 보유하고 있는 화장품에 대해 질문이 많아 대상선정 연락에 긴 시간 필요 (예상 20분 이상)\n​\n신청하기",
